// Bricks: collision + bounce + score + drawing, all in one place.
let bounced = false; // bounce at most once per frame (debt #1: neighbours)
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    // The grid gap (8 px) is smaller than the ball (14 px across), so a ball
    // at a seam overlaps two bricks in the same pass. Every overlap must
    // still destroy its brick, but the velocity must flip only once or the
    // two flips cancel out and the ball slips straight through.
    if (!bounced) {
      bounceOff(state.ball, brick);
      bounced = true;
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

